// Places on the map as grey discs with a white pictogram, the name set below. Which pictogram a
// place gets, how important it is when icons crowd, and how big the disc is at each zoom.
// Pure and DOM-free: shared by the map, the page, the glyph generator and the checks.
//
// Pictograms are lucide icon names (see lib/poi-glyphs.mjs, generated by
// scripts/build-poi-glyphs.mjs); `tooth` is drawn by us.

/** Map image ids are this prefix plus the pictogram name, e.g. `poi:utensils`. */
export const POI_IMAGE_PREFIX = 'poi:'
/** CSS pixels across the square image at icon-size 1. */
export const POI_BOX = 32
/** The disc inside the box: centre, outer radius and the width of its white ring. */
export const POI_DISC = { cx: 16, cy: 15.5, outer: 13.5, ring: 1.5 }
export const POI_COLOURS = { disc: '#878d92', ring: '#ffffff', glyph: '#ffffff', shadow: 'rgba(0,0,0,0.28)', label: '#40474d' }
/** CSS pixels across the pictogram at icon-size 1, and its stroke in 24-unit icon space. */
export const POI_GLYPH = { size: 16, stroke: 2.4 }
/** icon-size by zoom: small discs far out, full size from zoom 18. */
export const POI_SIZE_STOPS = [[12, 0.6], [14, 0.72], [16, 0.86], [18, 1]]
export const POI_MINZOOM = 12
/** Pixel size of the name under a disc (the overlay draws it in 600 weight Arial). */
export const POI_LABEL_FONT = 13
/** Far out only the important places show: rank ≤ 1 below zoom 14, ≤ 2 at 14, everything from 15. */
export const POI_RANK_FILTER = ['<=', ['get', 'rank'], ['step', ['zoom'], 1, 14, 2, 15, 9]]

const table = groups => {
  const out = Object.create(null)
  for (const [icon, keys] of Object.entries(groups)) {
    for (const key of keys.split(' ')) {
      if (key in out) throw new Error(`poi-icons: "${key}" is listed twice`)
      out[key] = icon
    }
  }
  return out
}

