/** Map objects that are not places of their own: streets, districts, numbered roads, houses. */
const TYPES = table({
  'signpost': 'street',
  'map-pinned': 'district',
  'route': 'route',
  'house': 'house',
  'map-pin': 'label',
})

const RELIGION = table({ 'church': 'christian', 'flame': 'zoroastrian' })

// Lower is more important: sorted first, and kept further out (POI_RANK_FILTER).
const MAJOR = new Set(['hospital', 'graduation-cap', 'bus-front', 'ship', 'store', 'landmark', 'drama', 'clapperboard', 'ferris-wheel', 'castle', 'volleyball', 'building-2', 'library', 'binoculars', 'scale'])
const COMMON = new Set(['utensils', 'coffee', 'hamburger', 'bed-double', 'shopping-cart', 'fuel', 'pill', 'mosque', 'church', 'school', 'banknote', 'mail', 'shield', 'stethoscope', 'tooth', 'star', 'fire-extinguisher', 'paw-print', 'image', 'pickaxe', 'info', 'tent', 'mountain-snow'])
const MINOR = new Set(['credit-card', 'square-parking', 'toilet', 'glass-water', 'droplet', 'phone', 'car-taxi-front', 'arrow-left-right', 'trash-2', 'recycle', 'map-pin', 'house'])

// The tables have no prototype, so a tag value such as `constructor` finds nothing.
const own = (object, key) => typeof key === 'string' ? object[key] : undefined

function iconOf(id, tags) {
  if (id.startsWith('house:')) return 'house'
  if (id.startsWith('point:') || id.startsWith('label:')) return 'map-pin'
  const type = tags['atlas:type']
  if (type === 'business') return own(BUSINESS, tags['atlas:category']) || 'building-2'
  const typed = own(TYPES, type)
  if (typed) return typed
  if (tags.amenity === 'place_of_worship') return own(RELIGION, tags.religion) || 'mosque'
  const historic = own(HISTORIC, tags.historic)
  if (historic && (tags.tourism === 'attraction' || !tags.amenity)) return historic
  const amenity = own(AMENITY, tags.amenity) || own(HEALTHCARE, tags.healthcare)
  if (amenity) return amenity
  if (tags.shop && tags.shop !== 'no') return own(SHOP, tags.shop) || 'shopping-bag'
  return own(TOURISM, tags.tourism) || own(LEISURE, tags.leisure) || (tags.tourism ? 'star' : 'map-pin')
}

/** The pictogram of a place and its rank, 0 (always shown) to 4 (only close in). */
export function poiStyle(id, tags) {
  const safe = tags || {}, icon = iconOf(String(id || ''), safe), type = safe['atlas:type']
  const rank = type === 'business' ? 0
    : type === 'landmark' || type === 'route' || safe.shop === 'mall' || safe.shop === 'department_store' || MAJOR.has(icon) ? 1
    : safe.amenity === 'shelter' || MINOR.has(icon) ? 4
    : COMMON.has(icon) ? 2 : 3
  return { icon, rank }
}

/**
 * The places to put on the map around a centre: the `limit` nearest, then up to `majors` more of
 * the nearest important ones (rank ≤ 1), so a zoomed-out view still shows hospitals, markets and
 * museums across the screen rather than only the few inside the nearest cluster.
 */
export function poiNearby(places, lon, lat, limit = 300, majors = 100) {
  const cos = Math.cos(lat * Math.PI / 180)
  const sorted = places.map(place => ({ place, gap: Math.hypot(place.lat - lat, (place.lon - lon) * cos) }))
    .sort((a, b) => a.gap - b.gap)
  const out = sorted.slice(0, limit).map(item => item.place)
  for (let i = limit, extra = 0; i < sorted.length && extra < majors; i++) {
    const place = sorted[i].place
    if (rankOf(place) <= 1) { out.push(place); extra++ }
  }
  return out
}

// A place object's rank, worked out once: the page hands the same objects over on every map move.
const ranks = new WeakMap()
function rankOf(place) {
  let rank = ranks.get(place)
  if (rank === undefined) ranks.set(place, rank = poiStyle(place.id, place.tags).rank)
  return rank
}

/** Every pictogram poiStyle can return, sorted: the list the glyph generator draws. */
export const POI_ICON_NAMES = [...new Set([
  ...[AMENITY, SHOP, TOURISM, HISTORIC, LEISURE, HEALTHCARE, BUSINESS, TYPES, RELIGION].flatMap(Object.values),
  'mosque', 'shopping-bag', 'star', 'map-pin', 'building-2',
])].sort()

/** icon-size at a zoom: linear between POI_SIZE_STOPS, held at the ends. */
export function poiIconScale(zoom) {
  const stops = POI_SIZE_STOPS
  if (!(zoom > stops[0][0])) return stops[0][1]
  for (let i = 1; i < stops.length; i++) {
    const [z1, s1] = stops[i]
    if (zoom <= z1) {
      const [z0, s0] = stops[i - 1]
      return s0 + (s1 - s0) * (zoom - z0) / (z1 - z0)
    }
  }
  return stops[stops.length - 1][1]
}

/** CSS pixels from a place's point to the edge of its disc. */
export const poiRadius = zoom => poiIconScale(zoom) * POI_DISC.outer

/** CSS pixels from a place's point down to the middle of its name: under the disc, a 2 px gap. */
export const poiLabelOffset = zoom => poiIconScale(zoom) * (POI_DISC.cy - POI_BOX / 2 + POI_DISC.outer) + 2 + POI_LABEL_FONT / 2

/** The MapLibre icon-size expression matching poiIconScale. */
export const poiIconSizeExpression = () => ['interpolate', ['linear'], ['zoom'], ...POI_SIZE_STOPS.flat()]
